    public static void main(Args _args)
{
    RMarketSymbolTable symbol;
    // Инициализация биржи
    RMarketTable market = RMarketTable::find('TestBybit');
    str s;

    while select market
        join symbol
    {

        s = RMarketJob_Instrument::getInstrumentInfo(market, symbol);

        Info(strFmt("%1 %2: %3", market.MarketId, symbol.SymbolId, s));
    }
}

public static str getInstrumentInfo(RMarketTable _market, RMarketSymbolTable _symbol)
{
    RMarketMethodInterface_Instrument apiMethod = RMarketMethodInterface::Instrument(_market.ApiType);
    apiMethod.setBaseUrl(_market.ApiUrl);
    //apiMethod.setApiKey(_apiKey);
    apiMethod.initParameters(_symbol.SymbolId);
    apiMethod.execute();
    //str createdOrderId = 
    return con2Str(apiMethod.getInfoCon(), ' | ');
}
